import cv2
import base64
import numpy as np


tmp = """"""

# print(tmp)

def string_to_descriptor(template_string):
    binary_data = base64.b64decode(template_string)
    return np.frombuffer(binary_data, dtype=np.uint8).reshape(-1, 32)

def verify_fingerprint(live_image_path, stored_template_string):
    # 1. Capture/Load the live image
    live_img = cv2.imread(live_image_path, cv2.IMREAD_GRAYSCALE)
    if live_img is None: return False
    
    # 2. Extract features from the live scan
    orb = cv2.ORB_create(nfeatures=500)
    _, live_descriptors = orb.detectAndCompute(live_img, None)
    
    if live_descriptors is None: return False
    
    # 3. Convert stored string back to descriptors
    stored_descriptors = string_to_descriptor(stored_template_string)
    
    # 4. Use Brute-Force Matcher (Hamming distance for ORB)
    bf = cv2.BFMatcher(cv2.NORM_HAMMING, crossCheck=True)
    matches = bf.match(live_descriptors, stored_descriptors)
    
    # 5. Filter good matches (distance < 50 is a common threshold for FS88)
    good_matches = [m for m in matches if m.distance < 50]
    
    # 6. Final Decision
    # Usually, 30+ good matches indicate a successful identity match
    score = len(good_matches)
    print(f"Match Score: {score}")
    
    return score > 30

# Example Usage
stored_str = "your_long_base64_string_from_db"
